// Which n8n? Cloud or self-hosted, scored from five answers.
const f = $input.first().json;
const business = String(f['Business name'] || 'your business').trim();
const email = String(f['Email'] || '').trim();
const workflows = Math.max(1, Number(f['Workflows you plan to run']) || 1);
const runs = Math.max(0, Number(f['Runs a month, all workflows together']) || 0);
const terminal = /^y/i.test(String(f['Comfortable with a terminal? (yes or no)'] || '').trim());

// n8n cloud list prices, billed yearly, September 2026. Check n8n.io/pricing, they change.
let plan, cloudCost, limits;
if (runs <= 2500 && workflows <= 5) { plan = 'Starter'; cloudCost = 20; limits = '2,500 runs and 5 active workflows'; }
else if (runs <= 10000 && workflows <= 15) { plan = 'Pro'; cloudCost = 50; limits = '10,000 runs and 15 active workflows'; }
else { plan = 'Enterprise'; cloudCost = null; limits = 'custom pricing above 10,000 runs or 15 workflows'; }

// A $5-6 server runs a small business. Step up to a ~$12 server past 20,000 runs a month.
const serverCost = runs > 20000 ? 12 : 6;

let pick, why, switchWhen;
if (!terminal) {
  pick = 'n8n cloud';
  why = 'Nobody on the team wants a terminal, so you are paying n8n to be the IT department. That is the right trade.';
  switchWhen = (cloudCost === null || cloudCost >= 50)
    ? 'Your bill is already at Pro or above. Pay a freelancer once to set up a self-hosted server (episode 8) and keep the difference every month.'
    : 'Switch when the bill reaches $50, or when someone on the team is happy in a terminal.';
} else if (workflows <= 2 && runs <= 2500) {
  pick = 'n8n cloud';
  why = 'Under three workflows the gap is about $14 a month. That does not buy back an evening of setup and a monthly update.';
  switchWhen = 'Switch at workflow three, or when you pass 2,500 runs a month.';
} else {
  pick = 'Self-hosted';
  why = 'You can run a terminal and you will own three or more workflows. Unlimited runs on a $6 server beats a metered plan.';
  switchWhen = 'Move to cloud only if you stop wanting to run updates and backups yourself.';
}

const cloudLine = cloudCost === null ? `n8n cloud: ${plan}, ${limits}.` : `n8n cloud: ${plan} at $${cloudCost} a month, ${limits}.`;
const selfLine = `Self-hosted: about $${serverCost} a month for a server, unlimited runs, plus your time.`;
const summary = `${cloudLine} ${selfLine} ${why} ${switchWhen}`;

return [{ json: { business, email, workflows, runs, terminal: terminal ? 'yes' : 'no', plan, cloudCost, serverCost, pick, why, switchWhen, summary } }];
